namespace Novior.MentorAgent.Abstractions.Core;

/// <summary>
/// Localization service for MentorAgent UI components.
/// In-memory only — no .resx files, no extra dependencies.
/// Automatic fallback to English for unsupported keys.
///
/// Supported languages: en, it, fr, de, es, pt, nl, pl, ja, zh
/// </summary>
public sealed class MentorLocalizer
{
    private readonly string _culture;

    public MentorLocalizer(MentorLanguage language)
        => _culture = language.ToIsoCode();

    public string Get(string key)
        => _strings.TryGetValue(key, out var langs)
            ? langs.TryGetValue(_culture, out var val) ? val
              : langs.TryGetValue("en", out var fallback) ? fallback
              : key
            : key;

